        vector(name: "sweep-ts-millis-1.0", payload: "WorkCam-Sig-v1\nversion=1.0\nrecord_id=a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1\nsequence_number=1\nprevious_record_hash=none\nphoto_hash=dac6f451810bc38390a3b6e278d686b332a77cf21b2ea95145ad73722b77035d\ncapture_timestamp=2026-11-25T12:00:00.500+00:00\ndevice_reported_time=2026-11-25T12:00:00.500+00:00\ndevice_id=device-A\nlocation=none\n", derB64: "MEQCIDMwjCHKJPDfI5wy+e8aVC0wq7cionjNgra+DJ6k46NrAiA+ypy0iX54MO5jXvnOysV5KQfrFNOd17ccE4J97D6gbw=="),
        vector(name: "sweep-ts-millis-1.1", payload: "WorkCam-Sig-v1.1\nversion=1.1\nrecord_id=a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1\nsequence_number=1\nprevious_record_hash=none\nphoto_hash=dac6f451810bc38390a3b6e278d686b332a77cf21b2ea95145ad73722b77035d\ncapture_timestamp=2026-11-25T12:00:00.500+00:00\ndevice_reported_time=2026-11-25T12:00:00.500+00:00\ndevice_id=device-A\nlocation=none\n", derB64: "MEUCIQDrvoeKvQtkD/GDwMBe8ytNLluCcFsdGJFNWUWJbuF+mgIgNct3rRroid1mHjJdawY3SoBXwxz5H5FxWSW69GoZ//E="),
